class TaskRunner(private val tasks: MutableList<String>) {
    var done = 0
    var shifted = 0

    fun runAll() {
        for (task in tasks) {
            if (task.isNotEmpty()) {
                done++
            }
        }
        tasks.clear()
    }
}

fun main() {
    val tasks = MutableList(1000) { "task-$it" }
    val runner = TaskRunner(tasks)
    runner.runAll()
    println("Done: ${runner.done}")
    println("Shifted: ${runner.shifted}")
}
